  public static String configToJson(Clickhouse.Config msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "Config is null");
    }
    try {
      Gson gson = new Gson();
      JsonObject obj = new JsonObject();
      if (msg.getRetentionDays() != 0) {
        obj.addProperty("retention_days", msg.getRetentionDays());
      }
      if (msg.getBatchSize() != 0) {
        obj.addProperty("batch_size", msg.getBatchSize());
      }
      if (msg.getFlushIntervalMs() != 0) {
        obj.addProperty("flush_interval_ms", msg.getFlushIntervalMs());
      }
      if (msg.getKeeperCount() != 0) {
        obj.addProperty("keeper_count", msg.getKeeperCount());
      }
      if (msg.getDataCount() != 0) {
        obj.addProperty("data_count", msg.getDataCount());
      }
      if (msg.getModeValue() != 0) {
        obj.addProperty("mode", nodeModeToString(msg.getMode()));
      }
      return gson.toJson(obj);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to serialize Config to JSON: " + e.getMessage(), e);
    }
  }

