  // ============ Validation ============
  public static void validateConfig(Clickhouse.Config msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate retentionDays (assert_ge: 1)
    if (msg.getRetentionDays() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field retentionDays must be >= 1, got: %s", msg.getRetentionDays()));
    }
    // Validate batchSize (assert_ge: 1)
    if (msg.getBatchSize() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field batchSize must be >= 1, got: %s", msg.getBatchSize()));
    }
    // Validate flushIntervalMs (assert_ge: 100)
    if (msg.getFlushIntervalMs() < 100) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field flushIntervalMs must be >= 100, got: %s", msg.getFlushIntervalMs()));
    }
    // Validate keeperCount (assert_ge: 1)
    if (msg.getKeeperCount() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field keeperCount must be >= 1, got: %s", msg.getKeeperCount()));
    }
    // Validate dataCount (assert_ge: 1)
    if (msg.getDataCount() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format("field dataCount must be >= 1, got: %s", msg.getDataCount()));
    }
  }

  public static void validateClickHouseNode(Clickhouse.ClickHouseNode msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate nodeId (assert_required)
    if (msg.getNodeId().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field nodeId is required");
    }
  }

