  public static Clickhouse.NodesValueResponse.Builder mergeNodesValueResponse(
      Clickhouse.NodesValueResponse dst, Clickhouse.NodesValueResponse src) {
    Clickhouse.NodesValueResponse.Builder builder = dst.toBuilder();
    if (!dst.hasValue() && src.hasValue()) {
      builder.setValue(src.getValue());
    } else if (dst.hasValue() && src.hasValue()) {
      builder.setValue(mergeClickHouseNode(dst.getValue(), src.getValue()).build());
    }
    if (!dst.getFound()) {
      builder.setFound(src.getFound());
    }
    return builder;
  }

  public static Clickhouse.NodesEntriesResponse.Builder mergeNodesEntriesResponse(
      Clickhouse.NodesEntriesResponse dst, Clickhouse.NodesEntriesResponse src) {
    Clickhouse.NodesEntriesResponse.Builder builder = dst.toBuilder();
    if (dst.getEntriesMap().isEmpty()) {
      builder.putAllEntries(src.getEntriesMap());
    } else {
      for (String mk : src.getEntriesMap().keySet()) {
        if (dst.getEntriesMap().containsKey(mk)) {
          builder.putEntries(
              mk,
              mergeClickHouseNode(dst.getEntriesMap().get(mk), src.getEntriesMap().get(mk))
                  .build());
        } else {
          builder.putEntries(mk, src.getEntriesMap().get(mk));
        }
      }
    }
    return builder;
  }

